function paginateAdmin44(host,rows,key){if(!host||!rows.length||host.querySelector('[data-list-tools="'+key+'"]'))return;const pref=adminListPrefs44[key]??={query:'',size:20,page:1};const tools=document.createElement('div');tools.className='admin-list-tools';tools.dataset.listTools=key;tools.innerHTML='<input placeholder="搜尋名稱、狀態或人員" value="'+esc(pref.query)+'"><label>每頁 <select>'+[20,50,100].map(n=>'<option '+(n===pref.size?'selected':'')+'>'+n+'</option>').join('')+'</select> 筆</label><span data-count></span><button type="button" data-prev>上一頁</button><button type="button" data-next>下一頁</button>';host.insertBefore(tools,rows[0].parentElement===host?rows[0]:null);const texts=new Map(rows.map(r=>[r,r.textContent.toLowerCase()]));function draw(){const filtered=rows.filter(r=>texts.get(r).includes(pref.query.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/pref.size));pref.page=Math.min(pref.page,pages);const shown=new Set(filtered.slice((pref.page-1)*pref.size,pref.page*pref.size));rows.forEach(r=>r.hidden=!shown.has(r));tools.querySelector('[data-count]').textContent=filtered.length+' 筆 · '+pref.page+'／'+pages+' 頁';tools.querySelector('[data-prev]').disabled=pref.page===1;tools.querySelector('[data-next]').disabled=pref.page===pages;}tools.querySelector('input').oninput=e=>{pref.query=e.target.value;pref.page=1;draw();};tools.querySelector('select').onchange=e=>{pref.size=Number(e.target.value);pref.page=1;draw();};tools.querySelector('[data-prev]').onclick=()=>{pref.page--;draw();};tools.querySelector('[data-next]').onclick=()=>{pref.page++;draw();};draw();}
const admin44=renderAdmin;renderAdmin=function(){admin44();if(currentUser.role!=='supervisor')return;for(const [kind,def]of Object.entries(bulkDefinitions)){if(!['cases','warehouse','plating','wire'].includes(kind))continue;const section=document.querySelector(def.section);if(!section)continue;const host=section.querySelector('.admin-card-body')||section;host.classList.add('compact-admin44');const bars=[...host.children].filter(x=>x.matches('.admin-actions,.wire-tools,.plating-actions'));if(bars.length){const unified=bars[0];unified.classList.add('compact-toolbar44');for(const b of bars.slice(1)){unified.append(...b.childNodes);b.remove();}host.prepend(unified);}if(kind==='warehouse')section.querySelectorAll('.bulk-warehouse-list .admin-row').forEach((row,i)=>{const p=state.projects[i],name=row.querySelector('strong');if(!p||!name)return;const b=document.createElement('button');b.type='button';b.className='project-name-link';b.textContent=p.name;b.onclick=()=>{selectedId=p.id;location.hash='#warehouse';render();};name.replaceWith(b);});const list=kind==='warehouse'?host.querySelector('.bulk-warehouse-list'):host;paginateAdmin44(list,[...list.querySelectorAll(':scope > .admin-row')],kind);}};
