selectionDialog=function(title,items,action,onApply,note=''){
 if(currentUser.role!=='supervisor'||cloudBusy||failedCandidate)return;let page=1,size=20,q='';const selected=new Set();
 modal(title,'<p>'+esc(note)+'</p><div class="bulk-toolbar"><input id="bulk-search44" placeholder="搜尋項目"><label><input type="checkbox" id="bulk-all">全選本頁</label><span id="bulk-count"></span></div><div class="bulk-list" id="bulk-list44"></div><div class="compact-pager"><button type="button" id="bulk-prev44">上一頁</button><span id="bulk-page44"></span><button type="button" id="bulk-next44">下一頁</button></div>',action,async()=>{const chosen=items.filter(x=>selected.has(String(x.id))&&!x.reason);if(!chosen.length)throw Error('請先勾選項目');if(!await confirmAction('確定'+action+' '+chosen.length+' 筆？\n'+chosen.map(x=>x.label).join('\n')))return;await onApply(chosen);$('#modal').close();renderAdmin();toast('已完成'+action+' '+chosen.length+' 筆');});
 function draw(){const filtered=items.filter(i=>i.label.toLowerCase().includes(q.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages);const visible=filtered.slice((page-1)*size,page*size),enabled=visible.filter(i=>!i.reason);$('#bulk-list44').innerHTML=visible.map(i=>'<label class="bulk-choice"><input type="checkbox" value="'+esc(String(i.id))+'" '+(selected.has(String(i.id))?'checked ':'')+(i.reason?'disabled':'')+'><span>'+esc(i.label)+(i.reason?'<small>'+esc(i.reason)+'</small>':'')+'</span></label>').join('')||'<p>尚無符合項目</p>';$('#bulk-count').textContent='已選 '+selected.size+' 筆（含其他頁）';$('#submit-modal').disabled=!selected.size;$('#bulk-page44').textContent=page+'／'+pages+' 頁';$('#bulk-prev44').disabled=page===1;$('#bulk-next44').disabled=page===pages;const all=$('#bulk-all'),count=enabled.filter(i=>selected.has(String(i.id))).length;all.checked=!!enabled.length&&count===enabled.length;all.indeterminate=count>0&&count<enabled.length;all.onchange=()=>{enabled.forEach(i=>all.checked?selected.add(String(i.id)):selected.delete(String(i.id)));draw();};$('#bulk-list44').querySelectorAll('input').forEach(i=>i.onchange=()=>{i.checked?selected.add(i.value):selected.delete(i.value);draw();});}
 $('#bulk-search44').oninput=e=>{q=e.target.value;page=1;draw();};$('#bulk-prev44').onclick=()=>{page--;draw();};$('#bulk-next44').onclick=()=>{page++;draw();};draw();
};
const warehouseExport44=exportWarehouse;exportWarehouse=async function(){if(!await authorizeExport())return;const projects=[['專案','本次開始日','本次套數','庫房位置','現有庫存'],...state.projects.map(p=>[p.name,p.production?.start||'',p.production?.sets||p.defaultSets||'',p.location||'',totalStock(p)])],parts=[['專案','零件','規格','每套需求','套數','總需求','本次已備','累計已收','現有庫存']],history=[['專案','開始日','套數','結束時間','零件','總需求','已備','庫存']];for(const p of state.projects){for(const i of p.parts)parts.push([p.name,i.name,i.spec,i.need,i.sets,totalNeed(i),preparedQuantity(p,i),i.received,inStock(p,i.id)]);for(const c of p.productionHistory||[])for(const i of c.parts||[])history.push([p.name,c.start,c.sets,c.endedAt,i.name,totalNeed(i),i.prepared,i.stock]);}await workbookDownload([['專案',projects],['零件與庫存',parts],['製作歷史',history]],'庫房管理資料.xlsx');};

